window.ScripturaLexicons.BDAG_PART_0322 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-01\" data-source=\"BDAG\" data-search=\"Σήθ, ὁ nome próprio masculino indeclinável Sete BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σήθ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Sete</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-02\" data-source=\"BDAG\" data-search=\"σηκός, οῦ, ὁ substantivo masculino ninho; sepultura, túmulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σηκός, οῦ, ὁ</td><td>substantivo masculino</td><td>ninho; sepultura, túmulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-03\" data-source=\"BDAG\" data-search=\"Σήμ, ὁ nome próprio masculino indeclinável Sem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σήμ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Sem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-04\" data-source=\"BDAG\" data-search=\"σημαίνω verbo comunicar; indicar, sugerir; significar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σημαίνω</td><td>verbo</td><td>comunicar; indicar, sugerir; significar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-05\" data-source=\"BDAG\" data-search=\"σημεῖον, ου, τό substantivo neutro sinal, marca, indicação; milagre, portento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σημεῖον, ου, τό</td><td>substantivo neutro</td><td>sinal, marca, indicação; milagre, portento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-06\" data-source=\"BDAG\" data-search=\"σημειόω verbo anotar; tomar especial nota, marcar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σημειόω</td><td>verbo</td><td>anotar; tomar especial nota, marcar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-07\" data-source=\"BDAG\" data-search=\"σημείωσις, εως, ἡ substantivo feminino sinal, aviso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σημείωσις, εως, ἡ</td><td>substantivo feminino</td><td>sinal, aviso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-08\" data-source=\"BDAG\" data-search=\"σήμερον advérbio de tempo hoje; agora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σήμερον</td><td>advérbio de tempo</td><td>hoje; agora</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-09\" data-source=\"BDAG\" data-search=\"σημικίνθιον variante; remissão ver σιμικίνθιον BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σημικίνθιον</td><td>variante; remissão</td><td>ver σιμικίνθιον</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-10\" data-source=\"BDAG\" data-search=\"σηπία, ας, ἡ substantivo feminino sépia, choco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σηπία, ας, ἡ</td><td>substantivo feminino</td><td>sépia, choco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-11\" data-source=\"BDAG\" data-search=\"σήπω verbo apodrecer, decompor-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σήπω</td><td>verbo</td><td>apodrecer, decompor-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-12\" data-source=\"BDAG\" data-search=\"σηρικός variante; remissão ver σιρικός BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σηρικός</td><td>variante; remissão</td><td>ver σιρικός</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-13\" data-source=\"BDAG\" data-search=\"σής substantivo masculino traça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σής</td><td>substantivo masculino</td><td>traça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-14\" data-source=\"BDAG\" data-search=\"σητόβρωτος, ον adjetivo comido por traças BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σητόβρωτος, ον</td><td>adjetivo</td><td>comido por traças</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-15\" data-source=\"BDAG\" data-search=\"σθενόω verbo fortalecer, tornar forte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σθενόω</td><td>verbo</td><td>fortalecer, tornar forte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-16\" data-source=\"BDAG\" data-search=\"σιαγών, όνος, ἡ substantivo feminino face, bochecha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σιαγών, όνος, ἡ</td><td>substantivo feminino</td><td>face, bochecha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-17\" data-source=\"BDAG\" data-search=\"σιαίνομαι verbo ser perturbado, incomodado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σιαίνομαι</td><td>verbo</td><td>ser perturbado, incomodado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-18\" data-source=\"BDAG\" data-search=\"Σίβυλλα, ης, ἡ substantivo feminino; nome próprio Sibila BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σίβυλλα, ης, ἡ</td><td>substantivo feminino; nome próprio</td><td>Sibila</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-19\" data-source=\"BDAG\" data-search=\"σιγάω verbo calar-se; manter em segredo, ocultar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σιγάω</td><td>verbo</td><td>calar-se; manter em segredo, ocultar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0322-20\" data-source=\"BDAG\" data-search=\"σιγή, ῆς, ἡ substantivo feminino silêncio, quietude BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σιγή, ῆς, ἡ</td><td>substantivo feminino</td><td>silêncio, quietude</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0322-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σήθ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σήθ</span>, <span class=\"greek\">ὁ</span> indecl. (<span class=\"hebrew\">שֵׁת</span>; LXX, ApcMos, Philo; TestBenj 10:6.—Joseph. apresenta <span class=\"greek\">Σῆθος</span>, <span class=\"greek\">ου</span> [Ant. 1, 68]) Sete, filho de Adão e Eva e pai de Enos (Gen 4:25f; 5:3-8; 1 Ch 1:1; Sir 49:16); na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:38</a>.—AKlijn, Seth in Jewish, Christian, and Gnostic Literature ’77.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σηκός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σηκός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Hom.+; inscr., pap.; 2 Macc 14:33; SibOr 3, 266; 281) prim. ‘curral, recinto’, de aves, ninho (Aristot., HA 6, 8), também de seres humanos, lugar de sepultamento, sepulcro, túmulo (Simonides Fgm. 5, 6 Diehl2 [26, 6 Page] em Diod S 11, 11, 6; também Diod S 17, 71, 7). No <span class=\"greek\">σηκός</span> que a ave Fênix preparou para si mesma 1 Cl 25:2f, os sentidos de ninho e túmulo fundem-se numa imagem impressionante.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σήμ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σήμ</span>, <span class=\"greek\">ὁ</span> indecl. (<span class=\"hebrew\">שֵׁם</span>; LXX; TestBenj 10:6; Philo; Just., D. 139, 2ff.—Joseph. apresenta <span class=\"greek\">Σήμας</span>, <span class=\"greek\">ᾳ</span> [Ant. 1, 143]) Sem, filho de Noé e pai de Arfaxade (Gen 5:32; 9:26f; 10:22; Sir 49:16); na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:36</a>.—BHHW III 1769.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σημαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σημαίνω</span> (<span class=\"greek\">σῆμα</span> ‘sinal’, v. os três verbetes seguintes; Hom.+; inscr., pap., LXX, TestJob; JosAs 23:8; Just., Tat. 17, 2; Mel., P. 95, 728) imperf. <span class=\"greek\">ἐσήμαινον</span>; fut. <span class=\"greek\">σημανῶ</span> LXX; 1 aor. <span class=\"greek\">ἐσήμανα</span> (X., Hell. 1, 1, 2; BGU 1097, 17; Judg 7:21; v. B-D-F §72; Mlt-H. 214f); perf. 1 pl. <span class=\"greek\">σεσημάγκαμεν</span> (Aristobul. em Eus., PE 13, 12, 7 [=Holladay p. 172, Fgm. 4, linhas 85f]). Pass.: aor. 3 sing. <span class=\"greek\">ἐσημάνθη</span> LXX; perf. 3 sing. <span class=\"greek\">σεσήμανται</span> 2 Macc 2:1.</p><p class=\"entry-text\">① dar a conhecer, relatar, comunicar (Trag., Hdt.+; inscr., pap., LXX, En; TestJob 6:3; EpArist; Philo, Post. Cai. 155 al.; Jos., Vi. 206; Just., D. 114, 2 al.) <span class=\"greek\">τὶ</span> algo, indicar acusações <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:27</a>. <span class=\"greek\">τινί</span> a alguém (En 106:13; 107, 2; TestJob 6:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:1</a>.</p><p class=\"entry-text\">② dar a entender algo acerca do futuro, indicar, sugerir, insinuar (Ezk. Trag. 83, em Eus., PE 9, 29, 6; Just., D. 78, 9 al.; cf. Appian, Liby. 104 §491 <span class=\"greek\">προσημαίνειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλλοντα</span>, de predição divina do futuro) seguido de ac. e inf. (Jos., Ant. 6, 50; cf. 8, 409) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:28</a>.—Também de uma fala que simplesmente oferece uma vaga sugestão do que há de acontecer (Heraclitus 93 em Plut., Mor. 404e, com ref. ao oráculo de Delfos <span class=\"greek\">οὔτε</span> <span class=\"greek\">λέγει</span>, <span class=\"greek\">οὔτε</span> <span class=\"greek\">κρύπτει</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">σημαίνει</span>; Epict. 1, 17, 18f; Jos., Ant. 7, 214; 10, 241) com uma oração interrogativa indireta subsequente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:33</a>; 18:32; 21:19.</p><p class=\"entry-text\">③ fornecer uma explicação para algo enigmático, querer dizer, significar (Pla., Cratylus 393A; Aristot., Physics 213b, 30, Rhet. 32f; Dionys. Hal., Thucyd. 31) B 15:4, em ref. a uma passagem da Escritura (Just., A I, 65, 4 <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">Ἀμὴν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Ἑβραί̈δι</span> <span class=\"greek\">φωνῇ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">Γένοιτο</span> <span class=\"greek\">σημαίνει</span>) <span class=\"greek\">ἡ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">σημαίνει</span> <span class=\"greek\">χίλια</span> <span class=\"greek\">ἔτη</span> pois um dia com o Senhor significa mil anos (v. Ps. 89:4).—DELG s.v. <span class=\"greek\">σῆμα</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σημεῖον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σημεῖον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (v. verbete precedente; Aeschyl., Hdt.+; inscr., pap., LXX, pseudepígr., Philo, Joseph., apolog.; empréstimo no rabínico; Hippol., Ref. 6, 27, 4; Did., Gen. 115, 9 ‘símbolo’; em geral ‘sinal’)</p><p class=\"entry-text\">① um sinal ou marca distintiva pelo qual algo é conhecido, sinal, marca, indicação (Diod S 3, 66, 3=indícios <span class=\"greek\">τῆς</span> <span class=\"greek\">παρουσίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; Cornutus 16 p. 21, 9.—Arrian, Anab. 6, 26, 4 de marcas na paisagem que indicam a direção; ParJer 5:11 <span class=\"greek\">τὰ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>; Just., A I, 55, 6 al.; Iren. 1, 14, 8 [Harv. I 143, 10]; Orig., C. Cels. 3, 43, 36 <span class=\"greek\">ς</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">θάνατον</span> <span class=\"greek\">ἐπιφανείας</span> <span class=\"greek\">αὐτοῦ</span> [sc. <span class=\"greek\">Ἰησοῦ</span>]; 2, 59, 6 das cicatrizes do Senhor ressuscitado <span class=\"greek\">τὰ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">κολάσεως</span>). <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">σημεῖον</span> isto (será) um sinal para vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:12</a> (cf. Is 37:30). <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">ἐπιστολῇ</span> esta é a marca de autenticidade em toda carta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:17</a> (Ps.-Pla., Ep. 13, 360a tem em seu início as palavras <span class=\"greek\">σύμβολον</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">ἐστιν</span>). De um sinal previamente combinado <span class=\"greek\">δοῦναί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">σημεῖον</span> (PFay 128, 7 <span class=\"greek\">ἔδωκεν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">σημεῖον</span> ‘ele nos deu um sinal’; Jos., Ant. 12, 404) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:48</a>; 1 Cl 12:7.—Um sinal de coisas vindouras (PsSol 15:9 <span class=\"greek\">τὸ</span> … <span class=\"greek\">σημεῖον</span> <span class=\"greek\">ἀπωλείας</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μετώπου</span> <span class=\"greek\">αὐτῶν</span>; Did., Gen. 191, 6; Philo, Op. M. 58 <span class=\"greek\">σημεῖα</span> <span class=\"greek\">μελλόντων</span>; Jos., Bell. 6, 285; 296; 297) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:7</a>. O acontecimento esperado é acrescentado no gen. <span class=\"greek\">τί</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σῆς</span> <span class=\"greek\">παρουσίας</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:3</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span> o sinal pelo qual se pode reconhecer a vinda do Ser Humano (Filho do Homem) vs. 30 (TGlasson, JTS 15, ’64, 299f [uma metáfora militar, ‘estandarte’; cf. Is 18:3; 1QM 3f]). <span class=\"greek\">τὰ</span> <span class=\"greek\">σημεῖα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">καιρῶν</span> os sinais dos tempos (do fim) (<span class=\"greek\">καιρός</span> 3b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:3</a>.—Um sinal de advertência (Plut., Caes. 737 [63, 1]; SibOr 3, 457; Mel., P. 14, 90) 1 Cl 11:2. Provavelmente de modo semelhante <span class=\"greek\">αἱ</span> <span class=\"greek\">γλῶσσαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σημεῖόν</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀπίστοις</span> as línguas (<span class=\"greek\">γλῶσσα</span> 3) servem de sinal (de advertência) aos incrédulos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:22</a>. Igualmente o sinal de Jonas (v. <span class=\"greek\">Ἰωνᾶς</span> 1) em Lucas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:29</a>, 30. Aqui o Ser Humano há de ser um sinal para sua geração, como Jonas o foi para os ninivitas; cf. <span class=\"greek\">οὗτος</span> <span class=\"greek\">κεῖται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σημεῖον</span> <span class=\"greek\">ἀντιλεγόμενον</span> (v. <span class=\"greek\">ἀντιλέγω</span> 2) 2:34 (cf. Is 11:12).—W-S. §30, 10d.—GRunze, Das Zeichen des Menschensohnes u. der Doppelsinn des Jonazeichens 1897 (contra ele PSchmiedel, Lit. Centralblatt 48, 1897, 513–15; novamente Runze, ZWT 41, 1898, 171–85; por fim PSchm. ibid. 514–25); PAsmussen, Protestantenblatt 37, 1904, 375–8; STyson, Bibl. World 33,1909, 96–101; CBowen, AJT 20, 1916, 414–21; JMichael, JTS 21, 1920, 146–59; JBonsirven, RSR 24, ’34, 450–55; HGale, JBL 60, ’41, 255–60; PSeidelin, Das Jonaszeichen, StTh 5, ’51, 119–31; AVögtle, Wikenhauser Festschr. ’53, 230–77; OGlombitza, D. Zeichen des Jona, NTS 8, ’62, 359–66.—No AT a circuncisão é <span class=\"greek\">σημεῖον</span> <span class=\"greek\">διαθήκης</span>=um sinal ou marca de pertencimento à aliança (Gen 17:11). Para Paulo esse sinal torna-se uma marca, ou selo (assim <span class=\"greek\">σημεῖον</span>: PRev 26, 5 [III a.C.]; PRein 9 introd. [II a.C.]; 35, 3; BGU 1064, 18) <span class=\"greek\">σημεῖον</span> <span class=\"greek\">ἔλαβεν</span> <span class=\"greek\">περιτομῆς</span> <span class=\"greek\">σφραγῖδα</span> recebeu a marca da circuncisão como selo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:11</a>. Na difícil passagem B 12:5 <span class=\"greek\">ἐν</span> <span class=\"greek\">σημείῳ</span> provavelmente deve ser entendido como ‘por meio de um sinal’; mas é possível que o texto esteja defeituoso (v. Windisch, Hdb. ad loc.; RKraft, Did. and Barnabas ’65, 119 nota: ‘padrão, norma’).—<span class=\"greek\">τὰ</span> <span class=\"greek\">σημεῖα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀποστόλου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:12</a>a pertence antes à categoria seguinte; os sinais do apóstolo (verdadeiro) (cf. SIG 831, 14 [117 d.C.] <span class=\"greek\">ἡγούμην</span> <span class=\"greek\">σημεῖα</span> <span class=\"greek\">ἀγαθῶν</span> <span class=\"greek\">ἀνδρῶν</span>) são, como demonstra o verbo <span class=\"greek\">κατειργάσθη</span> e o que se segue, os prodígios ou milagres por ele realizados.</p><p class=\"entry-text\">② um acontecimento que constitui indicação ou confirmação da intervenção de poderes transcendentes, milagre, portento</p><p class=\"entry-text\">ⓐ milagre</p><p class=\"entry-text\"><span class=\"greek\">α</span>. um milagre de origem divina, realizado pelo próprio Deus, por Cristo ou por homens de Deus (cf. Diod S 5, 70, 4 <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ς</span>. do jovem Zeus; 16, 27, 2 <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">σημεῖον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀπόλλωνος</span>; Strabo 16, 2, 35 <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ς</span>.; Appian, Ital. 8 §1 <span class=\"greek\">σημείων</span> <span class=\"greek\">γενομένων</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">Διός</span>, Hann. 56 §233; SIG 709, 25 [c. 107 a.C.] <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span> <span class=\"greek\">γενομένων</span> <span class=\"greek\">σαμείων</span>; PGM 1, 65; 74; Jos., Ant. 2, 274; 280; Mel., P. 78, 568): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:38</a>f; 16:1 (<span class=\"greek\">ς</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span>), 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:11</a> (<span class=\"greek\">ς</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span>, como Synes., Prov. 1, 7; v. OLinton, The Demand for a Sign from Heaven, StTh 19, ’65, 112–29; JGibson, JSNT 38, ’90, 37–66, um fenômeno que sugere livramento divino), 12; 16:17, 20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:16</a> (<span class=\"greek\">ς</span>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span>), 29 (v. 1 acima); 23:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:11</a>, 18, 23; 3:2; 4:54; 6:2, 14, 26, 30; 7:31; 9:16; 10:41; 11:47; 12:18, 37; 20:30 (sobre <span class=\"greek\">σημ</span>. como designação dos milagres de Jesus em J v. Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:11</a> e 6:26; JBernard, ICC John 1929, I introd. 176–86; CBarrett, The Gosp. acc. to St. John, ’55, 62–65); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:16</a>, 22 (<span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰάσεως</span> o milagre da cura); 8:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:22</a>; Agr 9. <span class=\"greek\">τί</span> <span class=\"greek\">εἴδετε</span> <span class=\"greek\">σημεῖον</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">γεννηθέντα</span> <span class=\"greek\">βασιλέα</span>; que espécie de sinal vistes sobre o rei recém-nascido? GJs 21:2 (codd.). <span class=\"greek\">τὸ</span> <span class=\"greek\">σημεῖον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐνάρετον</span> o sinal maravilhoso AcPl Ha 3,16.—<span class=\"greek\">σημεῖα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τέρατα</span> (Polyb. 3, 112, 8 <span class=\"greek\">σημείων</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τεράτων</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἱερόν</span>, <span class=\"greek\">πᾶσα</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἦν</span> <span class=\"greek\">οἰκία</span> <span class=\"greek\">πλήρης</span>; Plut., Alex. 706 [75, 1 sing.]; Appian, Bell. Civ. 2, 36 §144 <span class=\"greek\">τέρατα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σημεῖα</span> <span class=\"greek\">οὐράνια</span>; 4, 4 §14; Aelian, VH 12, 57; Philo, Mos. 1, 95, Aet. M. 2; Jos., Bell. 1, 28, Ant. 20, 168. Freq. na LXX: Ex 7:3; Dt 4:34; 6:22; 7:19 al.; Is 8:18; 20:3; Jer 39:21; Wsd 8:8; 10:16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.48\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:43</a>; 4:30; 5:12; 6:8; 7:36; 14:3; 15:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:4</a>; 1 Cl 51:5; B 4:14; 5:8. <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τέρατα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σημεῖα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:12</a>b (SSchreiber, Paulus als Wundertäter: BZNW 79, ’96) <span class=\"greek\">σημεῖα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δυνάμεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:13</a>.—1 Cl 25:1; 2 Cl 15:4. SMc-Casland, JBL 76, ’57, 149–52; MWhittaker, Studia Evangelica 5, ’68, 155–58.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. realizado por Satanás ou seus agentes para enganar o povo de Deus (v. Iren. 5, 28, 2 [Harv. V 401, 32]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:13</a>f; 16:14; 19:20. <span class=\"greek\">σημεῖα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τέρατα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:22</a> (GBeasley-Murray, A Commentary on Mk 13, ’57; EGrässer, D. Problem der Parusie-verzögerung, ’57, 152–70); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:9</a>; D 16:4.</p><p class=\"entry-text\">ⓑ portento, aparições aterradoras nos céus, nunca antes vistas, como portentos dos últimos dias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:11</a>, 25 (Appian, Bell. Civ. 4, 4 §14 <span class=\"greek\">σημεῖα</span> <span class=\"greek\">πολλά</span> em torno do sol; AscIs 3, 20); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:19</a> (cf. Jo 3:3); v. D 16:6. Daquilo que o vidente do Apocalipse vê <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οὐρανῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:1</a>, 3; 15:1. Dos sinais portentosos no céu e na terra por ocasião da morte de Jesus GPt 8:28 (cf. Da 6:28 Theod. <span class=\"greek\">σημεῖα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τέρατα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>; Diod S 38 + 39 Fgm. 5: ao fim de cada uma das oito eras ordenadas por Deus há um <span class=\"greek\">σημεῖον</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">θαυμάσιον</span>).—Sobre milagres v. SIG 1168–73; RLembert, Das Wunder bei Römern u. Griechen I 1905; RReitzenstein, Hellenist. Wundererzählungen 1906, OWeinreich, Antike Heilungswunder 1909, Gebet u. Wunder: WSchmid Festschr. 1929, 169ff; PWendland, De Fabellis Antiquis earumque ad Christianos Propagatione 1911; FKutsch, Attische Heilgötter u. Heilheroen 1913; WJayne, The Healing Gods of Ancient Civilizations 1925; RHerzog, D. Wunderheilungen v. Epidaurus ’31; PFiebig, Jüdische Wundergeschichten des ntl. Zeitalters 1911; ASchlatter, Das Wunder in d. Synagoge 1912.—RLehmann, Naturwissenschaft u. bibl. Wunderfrage 1930; GNaumann, Die Wertschätzung des Wunders im NT 1903; GTraub, Das Wunder im NT2 1907; KBeth, Die Wunder Jesu 1908; JThompson, Miracles in the NT 1911; LFonck, Die Wunder des Herrn im Ev.2 1907; LFillion, Les miracles de Jésus-Christ 1909/1910; PDausch, Die Wunder Jesu 1912; SEitrem, Nordisk Tidskrift for Filologie 5, 1919, 30–36; RBultmann, Die Gesch. der synopt. Tradition2 ’31, 223–60; RJelke, Die Wunder Jesu 1922; GShafto, The Wonders of the Kingdom 1924; JBest, The Miracles of Christ in the Light of our Present Day Knowledge ’37; TTorrance, Expository Studies in St. John’s Miracles ’38; ARichardson, The Miracle Stories of the Gospels ’41; AFridrichsen, Le Problème du Miracle dans le Christianisme primitif: Études d’ Hist. et de Phil. rel. XII 1925; HSchlingensiepen, Die Wunder des NT ’33; OPerels, D. Wunderüberlieferung der Synoptiker ’34; PSaintyves, Essais de folklore biblique 1923; GMarquardt, D. Wunderproblem in d. deutschen prot. Theologie der Gegenwart ’33; GDelling, D. Verständnis des Wunders im NT, ZST 24, ’55, 265–80, Zur Beurteilung des Wunders durch d. Antike: Studien zum NT ’70, 53–71; SMcCasland, Signs and Wonders, JBL 76, ’57, 149–52; CBarrett, The Gosp. Acc. to John ’55, 62–65; JCharlier, La notion de signe (sêmeion) dans J: RSPT 43, ’59, 434–48; PRiga, Signs of Glory (J): Int 17, ’63, 402–24; HvanderLoos, The Miracles of Jesus ’65; WNicol, The Semeia in the Fourth Gosp. ’72; para Atos v. FNeirynck, the Miracle Stories in the Acts of the Apostles, An Introduction, em Les Actes des Apôtres, ed. JKremer ’79, 169–213.—Esp. sobre a cura dos endemoninhados JWeiss, RE IV 408ff; JJaeger, Ist Jesus Christus ein Suggestionstherapeut gewesen? 1918; KKnur, M.D., Christus medicus? 1905; KDusberger, Bibel u. Kirche ’51, 114–17 (sinal precursor).—RGrant, Miracle and Natural Law in Graeco-Roman and Early Christian Thought ’52. V. também a lit. s.v. <span class=\"greek\">δαιμόνιον</span> 2.—V. ainda MWestermann, ed. <span class=\"greek\">ΠΑΡΑΔΟΞΑΓΡΑΦΟΙ</span>, Scriptores Rerum Mirabilium Graeci, 1839.—B. 914. DELG s.v. <span class=\"greek\">σῆμα</span>. M-M. DBS XII 1281–1330. EDNT. ABD IV 869 (lit.). TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σημειόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σημειόω</span> (<span class=\"greek\">σημεῖον</span>; desde Hippocr. V 672 L.; Theophr.; inscr., pap., Ps 4:7; TestSol, EpArist, Philo) 1 aor. méd. <span class=\"greek\">ἐσημειωσάμην</span>; usualmente, e em nossa lit. exclusivamente, na voz méd.</p><p class=\"entry-text\">① registrar por escrito, anotar, escrever (OGI 629, 168 <span class=\"greek\">ὡς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Κουρβούλων</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κράτιστος</span> <span class=\"greek\">ἐσημειώσατο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιστολῇ</span>) <span class=\"greek\">τὶ</span> algo, <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἱεραῖς</span> <span class=\"greek\">βίβλοις</span> 1 Cl 43:1.</p><p class=\"entry-text\">② prestar especial atenção a, marcar <span class=\"greek\">τινά</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:14</a>.—DELG s.v. <span class=\"greek\">σῆμα</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σημείωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σημείωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">σημειόω</span>; Chairemon, Fgm. 5, p. 32, 8; Plut., Mor. 961c; pap.; Ps 59:6; PsSol 4:2; TestJob 51:4; EpArist) sinal, aviso <span class=\"greek\">εἰς</span> <span class=\"greek\">ς</span>. <span class=\"greek\">γίνεσθαί</span> <span class=\"greek\">τινι</span> servir de (sinal de) advertência a alguém 1 Cl 11:2 (<span class=\"greek\">σημεῖον</span> 1).—DELG s.v. <span class=\"greek\">σῆμα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σήμερον</h1><div class=\"entry-meta\"><span>advérbio de tempo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σήμερον</span> adv. de tempo (Hom.+ [o ático <span class=\"greek\">τήμερον</span> não se encontra em nossa lit.: B-D-F §34, 1; Mlt-H. 279]; empréstimo no rabínico) hoje <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:11</a> (BMetzger, How Many Times Does <span class=\"greek\">ἐπιούσιος</span> Occur Outside the Lord’s Prayer? ET 60, ’57, 52–54; v. <span class=\"greek\">ἐπιούσιος</span>); 16:3; 21:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:21</a>; 23:43 (=antes que termine o dia de hoje, como Philostrat., Vi. Soph. 1, 25, 14); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:9</a> e freq.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:22</a> D (Ps 2:7); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:5</a>; 5:5; 1 Cl 36:4; GJs 19:2. Op. <span class=\"greek\">αὔριον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:13</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">σήμερον</span> <span class=\"greek\">ἡμέρα</span> (Dio Chrys. 31 [48], 3; SIG 1181, 11=prece de vingança de Reneia: Dssm., LO 351ff, esp. 357 [LAE 414 ff]; LXX) hoje, neste mesmo dia: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:15</a> (<span class=\"greek\">μέχρι</span> <span class=\"greek\">τὴς</span> <span class=\"greek\">ς</span>. <span class=\"greek\">ἡμέρας</span>, como 1 Esdr 8:74; Jos., Ant. 10, 265); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:26</a> (<span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">ἡμέρᾳ</span>, como Phlegon: 257 Fgm. 36, 3, 11 Jac.; Josh 5:9; PGM 4, 1580; 1699; 2062; 5, 187; 194); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:8</a> (<span class=\"greek\">ἕως</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ς</span>. <span class=\"greek\">ἡμέρας</span>, como UPZ 57, 3; Gen 19:38 al.; Just., D. 134, 5; Ath. 2, 1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:14</a> (<span class=\"greek\">ἄχρι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ς</span>. <span class=\"greek\">ἡμέρας</span>, como Jos., Ant. 7, 366). <span class=\"greek\">ὡς</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">ἡμέρα</span> GJs 19:2. Com elipse (BGU 598, 6; POxy 121, 6; LXX; JosAs 7:11; 15:4 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ς</span>. B-D-F §241, 2) <span class=\"greek\">ἡ</span> <span class=\"greek\">σήμερον</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:23</a>; 28:15 v.l. (ambos <span class=\"greek\">μέχρι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ς</span>. como Jos., Ant. 9, 28); 27:8 (<span class=\"greek\">ἕως</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ς</span>. como UPZ 5, 5 [163 a.C.]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:40</a> (<span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ς</span>.).—<span class=\"greek\">ἕως</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:15</a> (ViIs 4 [p. 69, 12 Sch.]; cf. Ps-Callisth. 1, 35, 9 <span class=\"greek\">μέχρι</span> <span class=\"greek\">ς</span>.).—Como os israelitas consideram que o dia começa ao pôr do sol, toda a noite pertence a um só e mesmo período de 24 horas: <span class=\"greek\">ς</span>. <span class=\"greek\">ταύτῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">νυκτί</span> nesta mesma noite <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:30</a>. Também simplesmente <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:11</a>; 22:34. Sobre <span class=\"greek\">ἐχθὲς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σήμερον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:8</a> v. <span class=\"greek\">ἐχθές</span>. Na perspectiva que vai do presente ao juízo vindouro <span class=\"greek\">ἄχρις</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σήμερον</span> <span class=\"greek\">καλεῖται</span> enquanto durar o ‘hoje’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:13</a> (cf. Philo, Leg. All. 3, 25 <span class=\"greek\">ὁ</span> <span class=\"greek\">αἰὼν</span> <span class=\"greek\">ἅπας</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σήμερον</span> <span class=\"greek\">παραμετρεῖται</span> e v. <span class=\"greek\">καλέω</span> 1d, fim).—Como o lat. hodie, <span class=\"greek\">ς</span>. serve para denotar um período limitado de tempo (Appian, Liby. 112 §532): <span class=\"greek\">σήμερον</span> … <span class=\"greek\">αὔριον</span>=agora … daqui a pouco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:28</a>. A expr. <span class=\"greek\">σήμερον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αὔριον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τρίτῃ</span> (ou <span class=\"greek\">καὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐχομένῃ</span>) refere-se a um breve período de tempo, cuja duração exata o falante não pode ou não deseja revelar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:32</a>f (JBlinzler, Klerusblatt ’44, 381–83).—V. ABonhöffer, Epiktet u. das NT 1911, 329f sobre <span class=\"greek\">σήμερον</span> no ensino ético de Epict.—B. 998. DELG s.v. <span class=\"greek\">τήμερον</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σημικίνθιον</h1><div class=\"entry-meta\"><span>variante; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σημικίνθιον</span> v. <span class=\"greek\">σιμικίνθιον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σηπία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σηπία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Aristoph. et al.) choco, sépia, com lampreia-marinha e polvo (com polvo: escólio sobre Pla. 160e) B 10:5 (v. Lev 11:10; também <span class=\"greek\">πολύπους</span> e <span class=\"greek\">σμύραινα</span>).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σήπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σήπω</span> (Hom. et al.; pap., LXX; Ath. 36, 2. At. ‘causar apodrecimento/decomposição’, pass. ‘apodrecer’) 1 aor. imper. 2 sing. <span class=\"greek\">σῆψον</span> Job 40:12; 2 perf. <span class=\"greek\">σέσηπα</span>, part. neut. <span class=\"greek\">σεσηπός</span>. Pass.: 2 fut. 3 sing. <span class=\"greek\">σαπήσεται</span> Ezk 17:9; 2 aor. 3 pl. <span class=\"greek\">ἐσάπησαν</span> LXX; perf. 3 sing. <span class=\"greek\">σέσηπται</span> (TestJob 43:7). O perf. at. ‘tornar podre’ é, em regra, empregado fora de nossa lit. (Hom. et al.) intransitivamente, como a pass., no sentido de ‘decompor-se’, e em nossa lit. exclusivamente assim. Decompor-se, apodrecer (TestJob 43:7; Philo, Aet. M. 125; Jos., C. Ap. 2, 143), 2 perf. at. estar decomposto <span class=\"greek\">ξύλον</span> <span class=\"greek\">σεσηπός</span> madeira podre Dg 2:2. <span class=\"greek\">σηπομένης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> enquanto a carne se decompõe 1 Cl 25:3 (Cyranides p. 7, 21 <span class=\"greek\">ἐσέσηπτο</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σάρξ</span>; Jos., Bell. 6, 164 <span class=\"greek\">σηπόμενον</span> <span class=\"greek\">σῶμα</span>). <span class=\"greek\">ὅπου</span> … <span class=\"greek\">Ἱερόνυμος</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὠτίου</span> <span class=\"greek\">ἐσήπετο</span> onde … Jerônimo sofria de um corrimento auricular AcPl Ha 5, 23. <span class=\"greek\">οὐ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">σηπόμενα</span>; Dg 2:4. De uma videira que rasteja pelo chão: <span class=\"greek\">σεσηπότα</span> <span class=\"greek\">φέρειν</span> produzir frutos podres Hs 2:3. Dos tesouros dos ricos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:2</a>.—DELG s.v. <span class=\"greek\">σήπομαι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σηρικός</h1><div class=\"entry-meta\"><span>variante; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σηρικός</span> v. <span class=\"greek\">σιρικός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σής</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σής</span> (desde Pind., Fgm. 209 [OxfT=222 Sch./M.] <span class=\"greek\">Διὸς</span> <span class=\"greek\">παῖς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">χρυσός</span>. <span class=\"greek\">κεῖνον</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">σὴς</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">κὶς</span> <span class=\"greek\">δάπτει</span> ‘o ouro é filho de Zeus: nem a traça nem a ferrugem podem consumi-lo’; LXX), <span class=\"greek\">σητός</span> (assim Aristot., HA 5, 32; Menand. et al.; LXX; Philo, Abr. 11.—O gen. clássico é <span class=\"greek\">σεός</span> v. Kühner-Bl. I 510f), <span class=\"greek\">ὁ</span> a traça, cujas larvas comem roupas (Menand., Fgm.538, 5 Kö.=540, 5 Kock; Lucian, Ep. Sat. 1, 21 <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">σητῶν</span> <span class=\"greek\">διαβρωθέντα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:19</a>f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:33</a>. Ser comido por traças como símbolo de fragilidade e destruição 1 Cl 39:5 (Job 4:19); B 6:2 (Is 50:9).—Vermes, especific. larvas que perfuram a madeira, parecem estar em vista (cf. Philo, Somn. 1, 77), visto que a <span class=\"greek\">σής</span> está danificando varas Hs 8, 1, 6f; 8, 4, 5; 8, 6, 4.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σητόβρωτος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σητόβρωτος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">σής</span>, <span class=\"greek\">βιβρώσκω</span>; Sb 7404, 28 [II d.C.]; SibOr Fgm. 3, 26; Hesych.) comido por traças <span class=\"greek\">ἱμάτια</span> (Job 13:28) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:2</a>.—New Docs 1, 77. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σθενόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σθενόω</span> (<span class=\"greek\">σθένος</span> ‘força’) fut. <span class=\"greek\">σθενώσω</span> (Herodian Gramm. 449, 21; Rhet. Gr. VII 260, 20; Hesych.) fortalecer, tornar forte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:10</a>.—DELG s.v. <span class=\"greek\">σθένος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιαγών, όνος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σιαγών</span>, <span class=\"greek\">όνος</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">ψίω</span> ‘mastigar’; Soph., X., Pla.+; usualmente em seu sentido orig. ‘mandíbula, osso maxilar’, assim também LXX [p. ex. Judg 15:14–17]; TestAbr A 16 p. 97, 14 [Stone p. 42]; Jos., Ant. 5, 300) bochecha (assim desde III a.C. [v. L-S-J-M s.v.], pap., LXX [p. ex. Is 50:6]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:29</a>; D 1:4 (sobre o assunto JWeismann, ZNW 14, 1913, 175f; JMoffatt, Exp. 8th ser., 7, 1914, 89; 8, 1914, 188f; UHolzmeister, ZKT 45, 1921, 334ff; HBryant, ET 48, ’37, 236f); GPt 3:9. <span class=\"greek\">τιθέναι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ς</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ῥαπίσματα</span> oferecer as faces aos golpes B 5:14 (Is 50:6).—B. 222. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιαίνομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σιαίνομαι</span> (Hippiatr. II 81, 5; POxy 1837, 2 [VI d.C.]; 1849, 2; Psaltes, Grammatik p. 333) ser perturbado/incomodado (a at.=‘causar incômodo’ ou ‘repugnância’: escólio sobre Lucian p. 261, 22 Rabe) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:3</a> v.l.—V. vDobschütz ad loc. e a lit. s.v. <span class=\"greek\">σαίνω</span>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σίβυλλα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino; nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σίβυλλα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Heraclitus [v. Plut., Mor. 397a] e Eur. et al.; SibOr 3, 815; 4, 22; TestSol 5:1 D; Jos., Ant. 1, 118; Just.; Tat. 41, 1; Ath. 30, 1) a Sibila, figura profética extática (v. Vergil, Aen. 6, 77–101 sobre a Sibila de Cumas associada a Apolo), inicialmente reconhecida como uma só pessoa e posteriormente concebida como uma pluralidade de pessoas (Pauly-W. II 2073ff; Kl. Pauly V 158–61; ABD VI 2–6 [lit.]) Hv 2, 4, 1 (v. MDibelius, Hdb. ad loc., Festgabe für AvHarnack 1921, 118).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιγάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σιγάω</span> (v. verbete seguinte) fut. <span class=\"greek\">σιγήσω</span> LXX; 1 aor. <span class=\"greek\">ἐσίγησα</span>; fut. méd. <span class=\"greek\">σιγήσομαι</span> Lam 3:49; part. perf. pass. <span class=\"greek\">σεσιγημένος</span></p><p class=\"entry-text\">① estar em silêncio, intr. (Hom. et al.; Sb 7183, 5; LXX; ApcMos 12; Jos., Vi. 175, Ant. 19, 44; Just., Mel.)</p><p class=\"entry-text\">ⓐ nada dizer, ficar quieto, guardar silêncio (Pind., N. 5, 18 <span class=\"greek\">τὸ</span> <span class=\"greek\">σιγᾶν</span> <span class=\"greek\">πολλάκις</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">σοφώτατον</span> <span class=\"greek\">ἀνθρώπῳ</span> <span class=\"greek\">νοῆσαι</span>; Just., D. 137, 3; Mel., P. 94, 723) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.61\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:61</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:40</a> D; 20:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:17</a>; 15:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:28</a> (ESchüsler-Fiorenza, In Memory of Her ’83, 230–33; PTomson, Paul and the Jewish Law ’90, 137). Resposta a uma acusação <span class=\"greek\">Ἰωσὴφ</span> <span class=\"greek\">ἐσίγησεν</span> GJs 15:4 (cf. Just., D. 102, 5 [sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:63</a>]). <span class=\"greek\">αἱ</span> <span class=\"greek\">γυναῖκες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐκκλησίαις</span> <span class=\"greek\">σιγάτωσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.34\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:34</a> (cf. a atitude helênica Od. 18, 184, também 17, 57; 21, 386; 22, 398; Eur., Heracl. 476f <span class=\"greek\">γυναικὶ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">σιγή</span> … <span class=\"greek\">κάλλιστον</span>, <span class=\"greek\">εἴσω</span> <span class=\"greek\">θ</span>’ <span class=\"greek\">ἥσυχον</span> <span class=\"greek\">μένειν</span> <span class=\"greek\">δόμων</span>=para uma mulher, o melhor é o silêncio e permanecer tranquila em casa; quanto à perspectiva cultural helênica sobre a agressividade feminina, v. VLeinieks, the City of Dionysos ’96, 277–302; v. a lit. s.v. <span class=\"greek\">γυνή</span> 1. Também RSeeberg, Aus Rel. u. Gesch., Ges. Aufs. I 1906, 128–44; HHöpfl, Bened. Monatsschr. 14, ’32, 63–77; GDautzenberg, Urchristl. Prophetie, ’75, 253–90; GFetzer, Das Weib schweige in der Gemeinde ’63.—PSchmiedel, JWeiss, WBousset ad loc., HWindisch [v. <span class=\"greek\">γυνή</span> 1], RBultmann [ThBl 12, ’33, 362] consideram os vs. 34f uma glosa secundária; sobre a história da crítica textual, v. CNiccum, NTS 43, ’97, 242–55; cf. PPayne, NTS 44, ’98, 152–58; note-se também a diferenciação de gênero nas leis sagradas SEG XLIII nos. 1293 e 1310); 1 Cl 35:9 (Ps 49:21); IEph 6:1; 15:1f (op. <span class=\"greek\">λαλεῖν</span>, como Alex. Aphr., Fat. 9 p. 175, 23 Br.); IPhld 1:1 (op. <span class=\"greek\">λαλεῖν</span>).—refrear a língua (cf. sentido b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:36</a>.</p><p class=\"entry-text\">ⓑ parar de falar, ficar em silêncio (ApcMos 12; Just., D. 57, 1 al.; Mel., P. 26, 184; Chariton 5, 7, 8; Synes., Kingship 29 p. 32a; SibOr 3, 473) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:41</a> D; 15:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:30</a>; MPol 7:2 v.l.—No sentido de ‘perder a faculdade da fala’ <span class=\"greek\">τῷ</span> … <span class=\"greek\">καιρῷ</span> <span class=\"greek\">ἐκείνῳ</span> <span class=\"greek\">Ζαχαρίας</span> <span class=\"greek\">ἐσίγησεν</span> GJs 10:2.</p><p class=\"entry-text\">② impedir que algo se torne conhecido, manter em segredo, ocultar, trans. <span class=\"greek\">τὶ</span> algo (Pind. et al.; Chariton 3, 10, 1; POxy 471, 41 [II d.C.]; Jos., Ant. 17, 309) <span class=\"greek\">Παῦλος</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">σιγῶν</span> (v.l. <span class=\"greek\">σιωπῶν</span>) <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> Paulo não se calava a respeito da mensagem (de Deus) AcPl Ha 9, 17. Pass. <span class=\"greek\">μυστήριον</span> <span class=\"greek\">χρόνοις</span> <span class=\"greek\">αἰωνίοις</span> <span class=\"greek\">σεσιγημένον</span> um segredo que esteve oculto durante longas eras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:25</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:36</a> em 1a.—B. 1259. Schmidt, Syn. I 215–24, v. <span class=\"greek\">σιωπάω</span>. DELG s.v. <span class=\"greek\">σιγή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0322-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιγή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σιγή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (v. verbete precedente; Hom. et al.; Wsd 18:14; 3 Macc 3:23; En 89:46; EpArist; Jos., Vi. 417; Just., D. 103, 9; Ath., R. 19 p. 71, 30) ausência de todo ruído, quer produzido pela fala, quer por qualquer outra coisa, silêncio, quietude 1 Cl 21:7. <span class=\"greek\">σιγῆς</span> <span class=\"greek\">ὑπαρχούσης</span> quando havia silêncio a bordo AcPl Ha 7, 25. <span class=\"greek\">πολλῆς</span> <span class=\"greek\">σιγῆς</span> <span class=\"greek\">γενομένης</span> quando se fez um grande silêncio = quando ficaram em silêncio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:40</a> (igualmente Ps.-Callisth. 2, 15, 6; sem <span class=\"greek\">πολλῆς</span> Arrian, Anab. 4, 12, 2; Vi. Aesopi W 87 P.; Jos., Vi. 141, Ant. 5, 236); cf. o silêncio dramático em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:1</a>, que pode implicar ausência tanto de sons da fala quanto de outros tipos de som, pois a abertura dos seis selos precedentes é acompanhada quer por declarações verbais, quer por fenômenos celestes (v. Clemen2 391; WBeet, ET 44, ’33, 74–76). <span class=\"greek\">σιγὴν</span> <span class=\"greek\">ἔχειν</span> estar em silêncio (Appian, Hann. 14 §60; Arrian, Anab. 5, 1, 4; Paroem. Gr.: App. 3, 7) Hs 9, 11, 5. <span class=\"greek\">ἀνάπαυσιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σιγῇ</span> repouso em silêncio GMary 463, 2. Cristo é chamado <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">λόγος</span>, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">σιγῆς</span> <span class=\"greek\">προελθών</span> Palavra (de Deus), procedente do silêncio=sem expressão audível IMg 8:2 (cf. o corolário: <span class=\"greek\">ἃ</span> … <span class=\"greek\">οὖς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἠκουσεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:9</a>; para outras opiniões sobre o texto e o assunto, v. Hdb. ad loc.; H-WBartsch, Gnost. Gut u. Gemeindetradition b. Ign. v. Ant. ’40. Sobre a divindade que é silêncio e que só pode ser devidamente adorada em silêncio, v. Mesomedes 1, 1–3 [=Coll. p. 197], dirigindo-se à deusa: <span class=\"greek\">Ἀρχὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">γέννα</span> | <span class=\"greek\">πρεσβίστα</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">μᾶτερ</span> | <span class=\"greek\">καὶ</span> <span class=\"greek\">νὺξ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σιγά</span>; Porphyr., Abst. 2, 34 <span class=\"greek\">διὰ</span> <span class=\"greek\">σιγῆς</span> <span class=\"greek\">καθαρᾶς</span> <span class=\"greek\">θρησκεύομεν</span> [<span class=\"greek\">θεόν</span>]; Sextus 578 <span class=\"greek\">τιμὴ</span> <span class=\"greek\">μεγίστη</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">γνῶσις</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σιγῇ</span>; PGM 4, 558ff <span class=\"greek\">λέγε</span>· <span class=\"greek\">σιγή</span>, <span class=\"greek\">σιγή</span>, <span class=\"greek\">σιγή</span>, <span class=\"greek\">σύμβολον</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ζῶντος</span> <span class=\"greek\">ἀφθάρτου</span>· <span class=\"greek\">φύλαξόν</span> <span class=\"greek\">με</span>, <span class=\"greek\">σιγή</span>; 1782. Hermes em Iambl., De Myst. 8, 3 <span class=\"greek\">ὸ̔</span> <span class=\"greek\">δὴ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">σιγῆς</span> <span class=\"greek\">μόνης</span> <span class=\"greek\">θεραπεύεται</span>. Herm. Wr. 10, 5 <span class=\"greek\">ἡ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">γνῶσις</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">βαθεῖα</span> <span class=\"greek\">σιωπή</span> <span class=\"greek\">ἐστι</span>. Martyr. Petri Aa I 96, 16ff.—HKoch, Ps.-Dionys. Areop. 1900, 128ff; OCasel, De Philosophorum Graecorum Silentio Mystico 1919, Vom hl. Schweigen: Bened. Monats-schr. 3, 1921, 417ff; GMensching, Das hl. Schweigen 1926).—DELG s.v. <span class=\"greek\">σῖγα</span>. M-M. Sv.</p></section></article>"};
